import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:examvault/features/result_checker/engine/hashed_index.dart';
import 'package:examvault/features/result_checker/engine/roll_index_engine.dart';
import 'package:flutter_test/flutter_test.dart';

/// Cross-language contract test.
///
/// The published index is hashed in Python (`tools/hashed_index.py`) and searched
/// in Dart. If the two normalisations or digests drift, every lookup silently
/// returns "not selected" — the worst possible failure mode for this app. The
/// fixed vectors below are generated by the Python side and pinned here, so a
/// mismatch fails CI instead of a student.
void main() {
  const salt = '00112233445566778899aabbccddeeff';

  group('digest parity with tools/hashed_index.py', () {
    // Generated by: python3 tools/hashed_index.py
    const vectors = {
      '125130000008': '87b1cfc91076e889',
      ' 1251 3000 0023 ': 'd0d742f478d72d1a',
      '125130000032': '4cbf3e9f3ea7f625',
    };

    vectors.forEach((roll, expected) {
      test('"$roll" hashes identically in both languages', () {
        expect(HashedRollIndex.digest(roll, salt), expected);
      });
    });

    test('normalisation strips nbsp, zero-width, dashes and spaces', () {
      expect(
        HashedRollIndex.normalise(' 1251\u00a03000\u200b0023 '),
        '125130000023',
      );
      expect(HashedRollIndex.normalise('ab\u2013cd'), 'ABCD');
      expect(HashedRollIndex.normalise('ab\u2014cd'), 'ABCD');
      expect(HashedRollIndex.normalise('ab cd'), 'ABCD');
    });
  });

  group('HashedRollIndex', () {
    HashedRollIndex indexOf(List<String> rolls) {
      final hashes = rolls.map((r) => HashedRollIndex.digest(r, salt)).toList()
        ..sort();
      return HashedRollIndex(
        salt: salt,
        hashes: hashes,
        total: rolls.length,
        sorted: true,
      );
    }

    test('finds present rolls and rejects absent ones', () {
      final index = indexOf(['125130000008', '125130000023', '125130000032']);

      expect(index.contains('125130000008'), isTrue);
      expect(index.contains('125130000032'), isTrue);
      expect(index.contains('125130000999'), isFalse);
    });

    test('a different salt cannot be used to probe another exam', () {
      final a = indexOf(['125130000008']);
      final b = HashedRollIndex(
        salt: 'ffffffffffffffffffffffffffffffff',
        hashes: a.hashes,
        total: 1,
        sorted: true,
      );

      expect(a.contains('125130000008'), isTrue);
      expect(
        b.contains('125130000008'),
        isFalse,
        reason: 'salt is part of the digest, so indexes are not portable',
      );
    });

    test('decodes the v2 wire format', () {
      final decoded = jsonDecode(
        jsonEncode({
          'v': 2,
          'mode': 'sha256-8-salted',
          'salt': salt,
          'total': 2,
          'hashes': [
            HashedRollIndex.digest('125130000008', salt),
            HashedRollIndex.digest('125130000032', salt),
          ]..sort(),
        }),
      );

      final index = HashedRollIndex.decode(decoded);
      expect(index.total, 2);
      expect(index.contains('125130000008'), isTrue);
      expect(index.contains('125130000023'), isFalse);
    });

    test(
      'rejects a payload with no salt instead of silently matching nothing',
      () {
        expect(
          () => HashedRollIndex.decode({'v': 2, 'hashes': []}),
          throwsA(isA<FormatException>()),
        );
      },
    );
  });

  group('engine integration', () {
    test(
      'a v2 object is searched and reported as privacy-preserving',
      () async {
        final doc = {
          'v': 2,
          'mode': 'sha256-8-salted',
          'salt': salt,
          'total': 2,
          'hashes': [
            HashedRollIndex.digest('125130000008', salt),
            HashedRollIndex.digest('125130000032', salt),
          ]..sort(),
        };

        final bytes = Uint8List.fromList(
          gzip.encode(utf8.encode(jsonEncode(doc))),
        );

        final hit = await RollIndexEngine.searchCompressed(
          compressed: bytes,
          rollNumber: '125130000008',
        );
        expect(hit.state, RollLookupState.found);
        expect(hit.privacyPreserving, isTrue);
        expect(hit.totalRolls, 2);

        final miss = await RollIndexEngine.searchCompressed(
          compressed: bytes,
          rollNumber: '125130000031',
        );
        expect(miss.state, RollLookupState.notFound);
      },
    );

    test('the decoded index carries no roll numbers at all', () async {
      final doc = {
        'v': 2,
        'salt': salt,
        'total': 1,
        'hashes': [HashedRollIndex.digest('125130000008', salt)],
      };
      final bytes = Uint8List.fromList(
        gzip.encode(utf8.encode(jsonEncode(doc))),
      );

      final index = await RollIndexEngine.decodeInIsolate(bytes);
      expect(index.isPrivacyPreserving, isTrue);
      expect(
        index.rolls,
        isEmpty,
        reason: 'the device must never hold the candidate list',
      );
    });

    test('an unsorted v2 index degrades to a scan instead of lying', () {
      // decode() detects and stores `sorted`; contains() used to ignore it and
      // binary-search anyway — silently answering "not found" for rolls that
      // ARE on the list whenever a producer violated the sort contract.
      //
      // Hash order is arbitrary, so "shuffled" inputs can come out sorted by
      // luck (this test did, on its first run). Sort-then-reverse guarantees
      // the descending order that trips the detector.
      final hashes = [
        HashedRollIndex.digest('125130000008', salt),
        HashedRollIndex.digest('125130000023', salt),
        HashedRollIndex.digest('125130000032', salt),
      ]..sort();
      final doc = {
        'salt': salt,
        'total': hashes.length,
        'hashes': hashes.reversed.toList(),
      };
      final index = HashedRollIndex.decode(doc);
      expect(index.sorted, isFalse);
      expect(index.contains('125130000008'), isTrue);
      expect(index.contains('125130000023'), isTrue);
      expect(index.contains('125130000032'), isTrue);
      expect(index.contains('999999999999'), isFalse);
    });

    test('a plaintext v1 array still works (local fixtures only)', () async {
      final bytes = Uint8List.fromList(
        gzip.encode(utf8.encode(jsonEncode(['125130000008']))),
      );
      final result = await RollIndexEngine.searchCompressed(
        compressed: bytes,
        rollNumber: '125130000008',
      );

      expect(result.state, RollLookupState.found);
      expect(result.privacyPreserving, isFalse);
    });
  });
}
